import * as React from 'react';
import { BarChart } from '@mui/x-charts/BarChart';

export default function BallBoxBarChartComponent({ dataBarChart }) {
    return (
        <BarChart
            xAxis={[{
                scaleType: 'band', data: ["Đỏ", "Xanh", "Vàng"], colorMap: {
                    type: "ordinal",
                    colors: ['#FF0000', '#008000', '#FFD700'],
                },
            }]}
            series={[
                {
                    data: dataBarChart, // Values for heads and tails

                },

            ]}
            width={500}
            height={300}
        />
    );
}