import React, { useEffect, useState } from 'react';
import './ball_box.css'; // Import file CSS
import { IconMinus, IconPlus } from '@tabler/icons-react';
import { Box, Button, Grid, TextField, Typography } from '@mui/material';
import PieChartComponent from 'src/components/chart/PieChart';
import BallBoxPieChart from 'src/components/chart/BallBoxPieChart';
import BallBoxBarChartComponent from 'src/components/chart/BallBoxBarChart';
import { forEach } from 'lodash';
import BallBoxChartComponent from 'src/components/chart/BallBoxLineChart';

const BallBox = () => {
    // Khởi tạo các quả bóng trong hộp (bao gồm số lượng từng loại)
    const [balls, setBalls] = useState(['red', 'green', 'yellow']);
    const [totalPicks, setTotalPicks] = useState(0); // Tổng số lần bắt bóng
    // State để lưu trữ số lần xuất hiện của mỗi loại bóng
    const [counts, setCounts] = useState({
        red: 0,
        green: 0,
        yellow: 0,
    });
    const [history, setHistory] = useState({
        History1: [0],
        History2: [0],
        History3: [0],
    });

    const [totalHistory, setTotalHistory] = useState([]);
    const handleAddToHistory = (value) => {
        setTotalHistory(prevHistory => [...prevHistory, value]);
    };
    // State để lưu số lần lấy bóng từ input
    const [pickCount, setPickCount] = useState(1);
    // Mảng lưu trữ lịch sử các lần random
    // Hàm để lấy bóng ngẫu nhiên từ hộp
    const pickBall = () => {
        if (balls.length === 0) {
            alert('Hộp bóng đã hết!');
            return;
        }

        let randomIndex = Math.floor(Math.random() * balls.length); // Lấy chỉ số ngẫu nhiên trong mảng balls
        const pickedBall = balls[randomIndex]; // Lấy quả bóng ngẫu nhiên
        setTotalPicks(totalPicks + 1);
        // Cập nhật số lần xuất hiện của loại bóng được chọn
        setCounts((prevCounts) => ({
            ...prevCounts,
            [pickedBall]: prevCounts[pickedBall] + 1,
        }));
        // console.log("randomIndex", balls[randomIndex]);
        if (balls[randomIndex] === "red") {
            randomIndex = 0;
        } else if (balls[randomIndex] === "green") {
            randomIndex = 1;
        } else {
            randomIndex = 2;
        }
        handleAddToHistory(randomIndex)
        setHistory(prevHistory => {
            const updatedHistory = { ...prevHistory };
            for (let index = 1; index <= 3; index++) {
                const historyKey = `History${index}`;
                if ((randomIndex + 1) === index) {
                    // Nếu không có trong sortedRandomValues, thay vì thêm 0, thêm giá trị cuối cùng của mảng history hiện tại
                    const lastValue = updatedHistory[historyKey].length > 0 ? updatedHistory[historyKey][updatedHistory[historyKey].length - 1] : 0;
                    updatedHistory[historyKey].push(lastValue + 1); // Thêm giá trị cuối cùng của lịch sử vào
                } else {
                    const lastValue = updatedHistory[historyKey].length > 0 ? updatedHistory[historyKey][updatedHistory[historyKey].length - 1] : 0;
                    updatedHistory[historyKey].push(lastValue); // Thêm giá trị cuối cùng của lịch sử vào
                }
            }
            return updatedHistory;
        });
    };
    // Hàm để thêm bóng vào hộp
    const addBall = (color) => {
        setBalls([...balls, color]); // Thêm bóng mới vào hộp
    };

    // Hàm để bớt bóng khỏi hộp
    const removeBall = (color) => {
        if (balls.filter(ball => ball === color).length === 0) {
            alert(`Không còn bóng màu ${color} trong hộp.`);
            return;
        }
        setBalls(balls.filter(ball => ball !== color)); // Loại bỏ một quả bóng màu cụ thể
    };
    const pickMultipleBall = () => {
        if (balls.length === 0) {
            alert('Hộp bóng đã hết!');
            return;
        }
        let newCounts = {
            red: 0,
            green: 0,
            yellow: 0,
        }; // Sao chép trạng thái đếm
        let updatedHistory = {
            History1: [0],
            History2: [0],
            History3: [0],
        }
        setTotalHistory([])
        let newBalls = [...balls]; // Sao chép trạng thái bóng
        let picks = 0; // Đếm số lần đã bắt
        for (let i = 0; i < pickCount; i++) {
            // if (newBalls.length === 0) break; // Dừng nếu hết bóng

            let randomIndex = Math.floor(Math.random() * newBalls.length); // Lấy chỉ số ngẫu nhiên
            const pickedBall = newBalls[randomIndex]; // Lấy bóng ngẫu nhiên
            // Cập nhật số lần xuất hiện của từng loại bóng
            newCounts[pickedBall] = newCounts[pickedBall] + 1;
            picks++;
            if (balls[randomIndex] === "red") {
                randomIndex = 0;
            } else if (balls[randomIndex] === "green") {
                randomIndex = 1;
            } else {
                randomIndex = 2;
            }
            handleAddToHistory(randomIndex)
            for (let index = 1; index <= 3; index++) {
                const historyKey = `History${index}`;
                if ((randomIndex + 1) === index) {
                    // Nếu không có trong sortedRandomValues, thay vì thêm 0, thêm giá trị cuối cùng của mảng history hiện tại
                    const lastValue = updatedHistory[historyKey].length > 0 ? updatedHistory[historyKey][updatedHistory[historyKey].length - 1] : 0;
                    updatedHistory[historyKey].push(lastValue + 1); // Thêm giá trị cuối cùng của lịch sử vào
                } else {
                    const lastValue = updatedHistory[historyKey].length > 0 ? updatedHistory[historyKey][updatedHistory[historyKey].length - 1] : 0;
                    updatedHistory[historyKey].push(lastValue); // Thêm giá trị cuối cùng của lịch sử vào
                }
            }
        }
        // Cập nhật trạng thái sau khi chọn bóng
        setCounts(newCounts);
        setBalls(newBalls); // Cập nhật lại danh sách bóng
        setTotalPicks(picks);
        setHistory(updatedHistory);
    };
    const resetAll = () => {
        setBalls(['red', 'green', 'yellow']);
        setCounts({ red: 0, green: 0, yellow: 0 });
        setTotalPicks(0);
        setPickCount(1);
        setDataPieChart([
            { id: 0, value: 0, label: 'Đỏ' },
            { id: 1, value: 0, label: 'Xanh' },
            { id: 2, value: 0, label: 'Vàng' },
        ]);
        setTotalHistory([])
    };
    console.log('kkkk', history);

    const [dataPieChart, setDataPieChart] = useState([
        { id: 0, value: 0, label: 'Đỏ' },
        { id: 1, value: 0, label: 'Xanh' },
        { id: 2, value: 0, label: 'Vàng' },
    ]);
    // Cập nhật phần trăm dữ liệu biểu đồ mỗi khi `counts` hoặc `totalPicks` thay đổi
    const updatePieChartData = () => {
        const totalBallsPicked = totalPicks;
        const redPercentage = ((counts.red / totalBallsPicked) * 100).toFixed(2) || 0;
        const greenPercentage = ((counts.green / totalBallsPicked) * 100).toFixed(2) || 0;
        const yellowPercentage = ((counts.yellow / totalBallsPicked) * 100).toFixed(2) || 0;

        setDataPieChart([
            { id: 0, value: parseFloat(redPercentage), label: 'Đỏ' },
            { id: 1, value: parseFloat(greenPercentage), label: 'Xanh' },
            { id: 2, value: parseFloat(yellowPercentage), label: 'Vàng' },
        ]);
    };

    // useEffect theo dõi sự thay đổi của `counts` và `totalPicks`
    useEffect(() => {
        if (totalPicks > 0) {
            updatePieChartData(); // Cập nhật dữ liệu biểu đồ mỗi khi tổng số bóng được bắt thay đổi
        }
    }, [counts, totalPicks]);
    const dataBarChart = [counts.red, counts.green, counts.yellow]

    const calculateMean = (arr) => {
        const sum = arr.reduce((acc, curr) => acc + curr, 0);  // Tính tổng các phần tử trong mảng
        const mean = sum / arr.length;  // Tính trung bình
        return mean;
    };
    const mean = calculateMean(totalHistory);
    function calculateMedian(arr) {
        // Sắp xếp mảng theo thứ tự tăng dần
        const nerArr = [...arr];
        nerArr.sort((a, b) => a - b);

        const n = nerArr.length;
        const mid = Math.floor(n / 2);

        // Nếu số phần tử là lẻ, trả về phần tử ở giữa
        if (n % 2 !== 0) {
            return nerArr[mid];
        } else {
            // Nếu số phần tử là chẵn, trả về trung bình của hai phần tử ở giữa
            return (nerArr[mid - 1] + nerArr[mid]) / 2;
        }
    }
    function calculateMode(arr) {
        const frequency = {}; // Đối tượng lưu tần suất xuất hiện của các phần tử trong mảng
        let maxFreq = 0; // Tần suất lớn nhất
        let mode = []; // Mảng chứa các số mốt
        // Đếm số lần xuất hiện của từng phần tử trong mảng
        for (let i = 0; i < arr.length; i++) {
            const num = arr[i];
            frequency[num] = (frequency[num] || 0) + 1;
            if (frequency[num] > maxFreq) {
                maxFreq = frequency[num];
                mode = [num]; // Nếu có tần suất cao hơn, reset mảng mode
            } else if (frequency[num] === maxFreq) {
                mode.push(num); // Nếu có tần suất bằng nhau, thêm vào mảng mode
            }
        }

        return mode;
    }
    const median = calculateMedian(totalHistory);
    const mode = calculateMode(totalHistory);
    console.log('totalHistory', totalHistory);

    return (
        <>
            <Typography
                fontWeight="bold"
                variant="h3"
                sx={{ mb: 2, textAlign: 'center' }}
            >
                Minh họa bài toán bắt bóng
            </Typography>
            <div className="ballbox-container">
                <Grid container spacing={2}>
                    <Grid item xs={12} sm={5}>
                        <div className="remaining">
                            <h3 style={{ marginBottom: '10px' }}>Số lượng bóng trong hộp: {balls.length} bóng</h3>
                            <div className="image-container">
                                <img src="/cabinet.jpg" alt="cabinet" width="100%" />
                                <button className="pick-ball-button" onClick={pickBall}>Lấy bóng</button>
                            </div>
                            <ul>
                                <li>
                                    <span className="red-ball"></span>{" "}Đỏ: <button style={{ marginLeft: '20px' }} className="add-ball-button" onClick={() => addBall('red')}>
                                        <IconPlus />
                                    </button>
                                    {balls.filter(ball => ball === 'red').length}
                                    <button className="remove-ball-button" onClick={() => removeBall('red')}>
                                        <IconMinus />
                                    </button>
                                </li>
                                <li>
                                    <span className="green-ball"></span> Xanh:
                                    <button className="add-ball-button" onClick={() => addBall('green')}>
                                        <IconPlus />
                                    </button>
                                    {balls.filter(ball => ball === 'green').length}
                                    <button className="remove-ball-button" onClick={() => removeBall('green')}>
                                        <IconMinus />
                                    </button>
                                </li>
                                <li>
                                    <span className="yellow-ball"></span>    Vàng:
                                    <button className="add-ball-button" onClick={() => addBall('yellow')}>
                                        <IconPlus />
                                    </button>
                                    {balls.filter(ball => ball === 'yellow').length}
                                    <button className="remove-ball-button" onClick={() => removeBall('yellow')}>
                                        <IconMinus />
                                    </button>
                                </li>
                            </ul>
                        </div>
                    </Grid>
                    <Grid item xs={12} sm={7}>
                        <h3>Tổng số lần bắt bóng: {totalPicks}</h3>
                        <div className="counts">
                            <h3>Số lần xuất hiện của mỗi màu bóng:</h3>
                            <ul>
                                <li>
                                    <span style={{ marginLeft: '-14px' }} className="red-ball"></span> Đỏ (0): {counts.red} ({dataPieChart[0]?.value + "%"})
                                </li>
                                <li>
                                    <span className="green-ball"></span> Xanh (1): {counts.green} ({dataPieChart[1]?.value + "%"})
                                </li>
                                <li>
                                    <span className="yellow-ball"></span> Vàng (2): {counts.yellow} ({dataPieChart[2]?.value + "%"})
                                </li>
                            </ul>
                        </div>

                        <Box className="pick-options" sx={{ display: 'flex', alignItems: 'center' }}>
                            <TextField
                                type="number"
                                value={pickCount}
                                onChange={(e) => setPickCount(parseInt(e.target.value))}
                                variant="outlined"
                                size="small"
                                sx={{ marginRight: 2 }}
                            />
                            <Button
                                variant="contained"
                                color="success"
                                onClick={pickMultipleBall}
                            >
                                Xác nhận
                            </Button>
                            <Button
                                variant="outlined"
                                color="secondary"
                                onClick={resetAll}
                                sx={{ ml: 2 }}
                            >
                                Làm mới
                            </Button>
                        </Box>
                        <h3 style={{ marginTop: "12px" }}> Kết quả:
                        </h3>
                        <h3 style={{ marginTop: "6px" }}>
                            {'['}
                            {totalHistory.map((item, index) => (
                                <>
                                    {item}
                                    {/* Kiểm tra nếu không phải phần tử cuối cùng thì thêm dấu ',' */}
                                    {(index + 1) !== totalHistory.length && ','}
                                    {/* Thêm thẻ <br /> sau mỗi 20 phần tử */}
                                    {(index + 1) % 20 === 0 && <br />}
                                </>
                            ))}
                            {']'}</h3>
                        <h3 style={{ marginTop: "12px" }}>Số trung bình: {isNaN(mean) ? 0 : mean}</h3>
                        <h3 style={{ marginTop: "12px" }}>Số trung vị: {isNaN(median) ? 0 : median}</h3>
                        <h3 style={{ marginTop: "12px" }}>Số mốt: {mode.join(", ")}</h3>
                    </Grid>
                </Grid>


            </div>
            <Grid container spacing={2} sx={{ pl: 5 }} >
                <Grid item xs={12}>
                    <Typography variant="h3" fontWeight="bold" sx={{ mb: 2 }}>
                        Biểu đồ
                    </Typography>
                    <Grid container spacing={2} sx={{ mt: 2 }}>
                        <Grid item xs={12} sm={12} md={6}>
                            <Typography variant='h6' sx={{ mb: 4 }}>Biểu đồ quạt</Typography>
                            <BallBoxPieChart data={dataPieChart} width={400} height={200} />
                        </Grid>
                        <Grid item xs={12} sm={12} md={6}>
                            <Typography variant='h6'>Biểu đồ cột</Typography>
                            <BallBoxBarChartComponent dataBarChart={dataBarChart} width={400} height={200} />
                        </Grid>
                        <Grid item xs={12} sm={12} md={12}>
                            <Typography variant='h6' sx={{ mb: 4 }}>Biểu đồ đoạn thằng</Typography>
                            <BallBoxChartComponent history={history} balls={balls} totalPicks={totalPicks} />
                        </Grid>
                    </Grid>
                </Grid>
            </Grid>
        </>
    );
};

export default BallBox;
