import React from 'react';
import { PieChart } from '@mui/x-charts/PieChart';

const BallBoxPieChart = ({ data, width, height }) => {
    // Đảm bảo dữ liệu có trường 'color' để chỉ định màu sắc cho từng phần
    const dataWithColor = data.map((item, index) => ({
        ...item,
        color: index === 0 ? '#FF0000' : index === 1 ? '#008000' : '#FFD700', // Đặt màu cho từng mục
    }));

    return (
        <PieChart
            series={[{
                data: dataWithColor, // Truyền dữ liệu đã có màu sắc
                arcLabel: (item) => `${item.value}%`,
                arcLabelMinAngle: 35,
                arcLabelRadius: '60%',
                arcLabelStyle: { fontWeight: 'normal', color: 'white' },
            }]}
            width={width}
            height={height}
        />
    );
};

export default BallBoxPieChart;
